import scala.io.Source
import org.apache.hadoop.conf.Configuration;
import org.apache.hadoop.fs.FileSystem;
import org.apache.hadoop.fs.Path;
import java.io.PrintWriter;

// Reading from URL
val json_content = Source.fromURL("https://api.tvmaze.com/shows/143/episodes").mkString

// Reading from the local file system (of Zeppelin)
// (from the machine where Zeppelin is located—typically a node that acts as a gateway)
// Very, very bad practice!!!
//val json_content = Source.fromFile("/home/training/thinclient_drives/GUACFS/svepisodes.json").mkString

// Reading from HDFS (Recommended)
//val json_content = spark.read.textFile("/user/training/svepisodes/svepisodes.json").collect().mkString("\n")

val conf = new Configuration() // Instantiating a configuration object automatically loads the system's default configuration files.
val fs= FileSystem.get(conf) // Access to the Hadoop / Cloudera file system (HDFS)

val output = fs.create(new Path("/tmp/svepisodes.json")) // Create the file in the HDFS /tmp directory
val writer = new PrintWriter(output) // Convert the "output" variable into a text writer.
writer.write(json_content) // It takes the "json_content" variable and sends it through the stream.
writer.close() // Release resources by calling the "close()" function
